    public static function tableExists($pdo,$table){if(!$pdo||!preg_match('/^[A-Za-z0-9_]+$/',(string)$table))return false;$key=self::key($pdo).':'.$table;if(array_key_exists($key,self::$tableCache))return self::$tableCache[$key];try{$st=$pdo->prepare('SHOW TABLES LIKE :table');$ok=$st&&$st->execute(array(':table'=>$table))&&$st->fetchColumn()!==false;self::$tableCache[$key]=$ok;return $ok;}catch(Exception $e){self::$tableCache[$key]=false;return false;}}
