    private static function encode($value){$json=json_encode($value,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);return is_string($json)?$json:null;}
    public static function decode($value){if(!is_string($value)||trim($value)==='')return array();$data=json_decode($value,true);return is_array($data)?$data:array();}
