    public static function createRunTableSql(){return "CREATE TABLE IF NOT EXISTS cpms_ai_cost_forecast_runs_v2 (\n id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,\n run_uid VARCHAR(64) NOT NULL,\n analysis_date DATE NOT NULL,\n target_ym CHAR(7) NOT NULL,\n snapshot_date DATE NULL,\n trigger_type VARCHAR(20) NOT NULL,\n run_status VARCHAR(20) NOT NULL,\n calculation_version VARCHAR(40) NOT NULL,\n source_fingerprint CHAR(64) NOT NULL,\n project_count INT UNSIGNED NOT NULL DEFAULT 0,\n success_count INT UNSIGNED NOT NULL DEFAULT 0,\n failure_count INT UNSIGNED NOT NULL DEFAULT 0,\n insufficient_count INT UNSIGNED NOT NULL DEFAULT 0,\n current_input_total DECIMAL(18,2) NOT NULL DEFAULT 0,\n final_forecast_total DECIMAL(18,2) NOT NULL DEFAULT 0,\n forecast_low_total DECIMAL(18,2) NOT NULL DEFAULT 0,\n forecast_high_total DECIMAL(18,2) NOT NULL DEFAULT 0,\n actor_employee_id INT NULL,\n actor_name VARCHAR(100) NULL,\n started_at DATETIME NOT NULL,\n finished_at DATETIME NULL,\n error_summary VARCHAR(500) NULL,\n created_at DATETIME NOT NULL,\n UNIQUE KEY uk_ai_cost_forecast_v2_run_uid (run_uid),\n KEY idx_ai_cost_forecast_v2_run_date (analysis_date,started_at),\n KEY idx_ai_cost_forecast_v2_run_status (run_status,started_at),\n KEY idx_ai_cost_forecast_v2_run_source (source_fingerprint)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4";}
    public static function createResultTableSql(){return "CREATE TABLE IF NOT EXISTS cpms_ai_cost_forecast_results_v2 (\n id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,\n run_id BIGINT UNSIGNED NULL,\n analysis_date DATE NOT NULL,\n target_ym CHAR(7) NOT NULL,\n snapshot_date DATE NOT NULL,\n project_id INT UNSIGNED NOT NULL,\n project_name_snapshot VARCHAR(190) NULL,\n project_status_snapshot VARCHAR(50) NULL,\n current_input_amount DECIMAL(18,2) NOT NULL DEFAULT 0,\n expected_completion_rate DECIMAL(8,3) NULL,\n expected_unentered_amount DECIMAL(18,2) NOT NULL DEFAULT 0,\n final_forecast_amount DECIMAL(18,2) NOT NULL DEFAULT 0,\n forecast_low_amount DECIMAL(18,2) NOT NULL DEFAULT 0,\n forecast_high_amount DECIMAL(18,2) NOT NULL DEFAULT 0,\n forecast_confidence_score DECIMAL(6,2) NULL,\n forecast_confidence_grade VARCHAR(20) NOT NULL,\n forecast_method VARCHAR(50) NOT NULL,\n fallback_level VARCHAR(40) NOT NULL,\n sample_count INT UNSIGNED NOT NULL DEFAULT 0,\n category_analyzable_rate DECIMAL(8,3) NOT NULL DEFAULT 0,\n cumulative_current_input_amount DECIMAL(18,2) NOT NULL DEFAULT 0,\n cumulative_projected_input_amount DECIMAL(18,2) NOT NULL DEFAULT 0,\n contract_amount DECIMAL(18,2) NOT NULL DEFAULT 0,\n projected_cumulative_cost_rate DECIMAL(8,3) NULL,\n contract_risk_grade VARCHAR(20) NOT NULL,\n overinput_grade VARCHAR(20) NOT NULL,\n missing_possibility_grade VARCHAR(20) NOT NULL,\n anomaly_count INT UNSIGNED NOT NULL DEFAULT 0,\n data_status VARCHAR(30) NOT NULL,\n calculation_version VARCHAR(40) NOT NULL,\n source_fingerprint CHAR(64) NOT NULL,\n method_data MEDIUMTEXT NULL,\n warning_data MEDIUMTEXT NULL,\n risk_data MEDIUMTEXT NULL,\n first_created_at DATETIME NOT NULL,\n last_calculated_at DATETIME NOT NULL,\n calculation_count INT UNSIGNED NOT NULL DEFAULT 1,\n created_at DATETIME NOT NULL,\n updated_at DATETIME NOT NULL,\n UNIQUE KEY uk_ai_cost_forecast_v2_result (analysis_date,target_ym,project_id),\n KEY idx_ai_cost_forecast_v2_project (project_id,analysis_date),\n KEY idx_ai_cost_forecast_v2_month (target_ym,analysis_date),\n KEY idx_ai_cost_forecast_v2_confidence (forecast_confidence_grade,analysis_date),\n KEY idx_ai_cost_forecast_v2_source (source_fingerprint)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4";}
    public static function createCategoryTableSql(){return "CREATE TABLE IF NOT EXISTS cpms_ai_cost_forecast_category_results_v2 (\n id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,\n run_id BIGINT UNSIGNED NULL,\n analysis_date DATE NOT NULL,\n target_ym CHAR(7) NOT NULL,\n snapshot_date DATE NOT NULL,\n project_id INT UNSIGNED NOT NULL,\n cost_type VARCHAR(40) NOT NULL,\n current_input_amount DECIMAL(18,2) NOT NULL DEFAULT 0,\n expected_completion_rate DECIMAL(8,3) NULL,\n expected_unentered_amount DECIMAL(18,2) NOT NULL DEFAULT 0,\n final_forecast_amount DECIMAL(18,2) NOT NULL DEFAULT 0,\n forecast_low_amount DECIMAL(18,2) NOT NULL DEFAULT 0,\n forecast_high_amount DECIMAL(18,2) NOT NULL DEFAULT 0,\n forecast_confidence_score DECIMAL(6,2) NULL,\n forecast_confidence_grade VARCHAR(20) NOT NULL,\n forecast_method VARCHAR(50) NOT NULL,\n fallback_level VARCHAR(40) NOT NULL,\n sample_count INT UNSIGNED NOT NULL DEFAULT 0,\n event_count INT UNSIGNED NOT NULL DEFAULT 0,\n average_input_lag_days DECIMAL(8,3) NULL,\n completion_volatility DECIMAL(8,3) NULL,\n late_bulk_rate DECIMAL(8,3) NULL,\n correction_rate DECIMAL(8,3) NULL,\n month_move_rate DECIMAL(8,3) NULL,\n overinput_grade VARCHAR(20) NOT NULL,\n missing_possibility_grade VARCHAR(20) NOT NULL,\n data_status VARCHAR(30) NOT NULL,\n calculation_version VARCHAR(40) NOT NULL,\n candidate_data MEDIUMTEXT NULL,\n anomaly_type_data MEDIUMTEXT NULL,\n first_created_at DATETIME NOT NULL,\n last_calculated_at DATETIME NOT NULL,\n calculation_count INT UNSIGNED NOT NULL DEFAULT 1,\n created_at DATETIME NOT NULL,\n updated_at DATETIME NOT NULL,\n UNIQUE KEY uk_ai_cost_forecast_v2_category (analysis_date,target_ym,project_id,cost_type),\n KEY idx_ai_cost_forecast_v2_category_project (project_id,analysis_date),\n KEY idx_ai_cost_forecast_v2_category_type (cost_type,analysis_date),\n KEY idx_ai_cost_forecast_v2_category_run (run_id)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4";}
    public static function requiredTables(){return array(self::RUN_TABLE=>self::createRunTableSql(),self::RESULT_TABLE=>self::createResultTableSql(),self::CATEGORY_TABLE=>self::createCategoryTableSql());}
    public static function installOrUpdate($pdo=null){$pdo=self::pdo($pdo);if(!$pdo)return array('ok'=>false,'message'=>'DB 연결 상태를 확인할 수 없습니다.');try{foreach(self::requiredTables() as $table=>$sql)if($pdo->exec($sql)===false)return array('ok'=>false,'message'=>'V2 예측 테이블을 설치하지 못했습니다.');self::$tableCache=array();return array('ok'=>self::isInstalled($pdo),'message'=>self::isInstalled($pdo)?'V2 예측 테이블 설치를 확인했습니다.':'V2 예측 테이블 구조를 확인해주세요.');}catch(Exception $e){error_log('[AI Forecast V2] install failed');return array('ok'=>false,'message'=>'V2 예측 테이블 설치를 확인하지 못했습니다.');}}
    public static function isInstalled($pdo=null){$pdo=self::pdo($pdo);if(!$pdo)return false;foreach(array_keys(self::requiredTables()) as $table)if(!self::tableExists($pdo,$table))return false;return true;}
    public static function schemaStatus($pdo=null){$pdo=self::pdo($pdo);$s=array('db_available'=>(bool)$pdo,'installed'=>false,'latest_result'=>array(),'latest_run'=>array(),'result_count'=>0);if(!$pdo)return $s;$s['installed']=self::isInstalled($pdo);if(!$s['installed'])return $s;try{$st=$pdo->query('SELECT * FROM `'.self::RESULT_TABLE.'` ORDER BY analysis_date DESC,id DESC LIMIT 1');$row=$st?$st->fetch(PDO::FETCH_ASSOC):false;$s['latest_result']=is_array($row)?$row:array();$st=$pdo->query('SELECT * FROM `'.self::RUN_TABLE.'` ORDER BY started_at DESC,id DESC LIMIT 1');$row=$st?$st->fetch(PDO::FETCH_ASSOC):false;$s['latest_run']=is_array($row)?$row:array();$st=$pdo->query('SELECT COUNT(*) FROM `'.self::RESULT_TABLE.'`');$s['result_count']=$st?(int)$st->fetchColumn():0;}catch(Exception $e){}return $s;}

    public static function weightedMedian($candidates)
    {
        $rows=array();$total=0.0;foreach($candidates as $row){if(!isset($row['value'])||!is_numeric($row['value']))continue;$weight=isset($row['weight'])?max(0,(float)$row['weight']):1;if($weight<=0)continue;$row['value']=(float)$row['value'];$row['weight']=$weight;$rows[]=$row;$total+=$weight;}
        if(count($rows)===0)return null;usort($rows,array(__CLASS__,'compareCandidate'));$running=0.0;foreach($rows as $row){$running+=$row['weight'];if($running>=$total/2)return $row['value'];}return $rows[count($rows)-1]['value'];
    }
    public static function compareCandidate($a,$b){if($a['value']==$b['value'])return 0;return $a['value']<$b['value']?-1:1;}
    private static function clamp($v,$min,$max){return max((float)$min,min((float)$max,(float)$v));}
    public static function confidenceGrade($score){if($score===null)return 'INSUFFICIENT';if($score>=85)return 'HIGH';if($score>=70)return 'MEDIUM';if($score>=50)return 'LOW';return 'VERY_LOW';}
    private static function confidence($pattern,$progressRate,$analyzableRate)
    {
        $scores=array();$weights=array();$months=isset($pattern['sample_month_count'])?(int)$pattern['sample_month_count']:0;$scores[]=min(100,$months/6*100);$weights[]=25;
        if(isset($pattern['expected_completion_rate'])&&$pattern['expected_completion_rate']!==null){$scores[]=self::clamp($pattern['expected_completion_rate'],0,100);$weights[]=20;}
        if(isset($pattern['completion_volatility'])&&$pattern['completion_volatility']!==null){$scores[]=self::clamp(100-(float)$pattern['completion_volatility']*2,0,100);$weights[]=20;}
        $scores[]=self::clamp(100-abs(100-(float)$progressRate)*0.25,40,100);$weights[]=15;$scores[]=self::clamp($analyzableRate,0,100);$weights[]=10;
        if(isset($pattern['correction_rate'])&&$pattern['correction_rate']!==null){$scores[]=self::clamp(100-(float)$pattern['correction_rate']-(float)$pattern['late_bulk_rate']*0.5,0,100);$weights[]=10;}
        $available=array_sum($weights);if($available<60)return null;$sum=0.0;for($i=0;$i<count($scores);$i++)$sum+=$scores[$i]*$weights[$i];return round($sum/$available,2);
    }
    private static function sourceFingerprint($context,$snapshots,$patterns){return hash('sha256',self::encode(array('context'=>$context,'snapshots'=>$snapshots,'patterns'=>$patterns,'version'=>self::CALCULATION_VERSION)));}
    private static function latestSnapshotContext($pdo){$empty=array('available'=>false,'snapshot_date'=>'','target_ym'=>'');if(!self::tableExists($pdo,self::SNAPSHOT_TABLE))return $empty;try{$st=$pdo->query('SELECT snapshot_date,target_ym FROM `'.self::SNAPSHOT_TABLE.'` ORDER BY snapshot_date DESC,id DESC LIMIT 1');$row=$st?$st->fetch(PDO::FETCH_ASSOC):false;if(!is_array($row))return $empty;return array('available'=>true,'snapshot_date'=>(string)$row['snapshot_date'],'analysis_date'=>(string)$row['snapshot_date'],'target_ym'=>(string)$row['target_ym']);}catch(Exception $e){return $empty;}}
    private static function loadSnapshots($pdo,$context){$cols=array_values(self::categories());$sql='SELECT snapshot_date,target_ym,project_id,project_name_snapshot,project_status_snapshot,contract_amount,cumulative_input_amount,monthly_input_amount,'.implode(',',$cols).' FROM `'.self::SNAPSHOT_TABLE.'` WHERE snapshot_date=:date AND target_ym=:ym ORDER BY project_id';try{$st=$pdo->prepare($sql);if(!$st||!$st->execute(array(':date'=>$context['snapshot_date'],':ym'=>$context['target_ym'])))return array();$rows=$st->fetchAll(PDO::FETCH_ASSOC);return is_array($rows)?$rows:array();}catch(Exception $e){return array();}}
    private static function oldForecastMap($pdo,$context){$map=array();if(!self::tableExists($pdo,self::OLD_FORECAST_TABLE))return $map;try{$sql='SELECT project_id,category_forecast_data FROM `'.self::OLD_FORECAST_TABLE.'` WHERE target_ym=:ym AND forecast_date=(SELECT MAX(forecast_date) FROM `'.self::OLD_FORECAST_TABLE.'` WHERE target_ym=:ym2)';$st=$pdo->prepare($sql);if(!$st||!$st->execute(array(':ym'=>$context['target_ym'],':ym2'=>$context['target_ym'])))return $map;foreach($st->fetchAll(PDO::FETCH_ASSOC) as $row)$map[(int)$row['project_id']]=self::decode($row['category_forecast_data']);}catch(Exception $e){}return $map;}
    private static function recentPaceMap($pdo,$context){$map=array();$start=date('Y-m-d',strtotime($context['snapshot_date'].' -14 days'));$cols=array_values(self::categories());try{$sql='SELECT snapshot_date,project_id,'.implode(',',$cols).' FROM `'.self::SNAPSHOT_TABLE.'` WHERE target_ym=:ym AND snapshot_date>=:start AND snapshot_date<=:end ORDER BY project_id,snapshot_date';$st=$pdo->prepare($sql);if(!$st||!$st->execute(array(':ym'=>$context['target_ym'],':start'=>$start,':end'=>$context['snapshot_date'])))return $map;foreach($st->fetchAll(PDO::FETCH_ASSOC) as $row){$p=(int)$row['project_id'];if(!isset($map[$p]))$map[$p]=array('first'=>$row,'last'=>$row);$map[$p]['last']=$row;}}catch(Exception $e){}return $map;}

    private static function calculateCategory($pdo,$snapshot,$cost,$column,$pattern,$oldCategory,$pace)
    {
        $current=isset($snapshot[$column])?(float)$snapshot[$column]:0.0;$progress=AiInputCompletionPatternService::progress($snapshot['snapshot_date'],$snapshot['target_ym'],$cost);$completion=isset($pattern['expected_completion_rate'])&&$pattern['expected_completion_rate']!==null?(float)$pattern['expected_completion_rate']:null;$minRate=AiInputCompletionPatternService::minCompletionRate($pdo);$candidates=array();
        if($completion!==null&&$completion>0){$weight=$completion<$minRate?10:40;$candidates[]=array('type'=>'COMPLETION_PATTERN','value'=>$current/($completion/100),'weight'=>$weight);}
        $oldValue=isset($oldCategory['forecast'])&&is_numeric($oldCategory['forecast'])?(float)$oldCategory['forecast']:null;if($oldValue!==null)$candidates[]=array('type'=>'BASIC_FORECAST','value'=>$oldValue,'weight'=>25);
        $detail=AiInputCompletionPatternService::decode(isset($pattern['detail_data'])?$pattern['detail_data']:'');$historical=isset($detail['historical_final_median'])&&is_numeric($detail['historical_final_median'])?(float)$detail['historical_final_median']:null;if($historical!==null)$candidates[]=array('type'=>'HISTORICAL_MEDIAN','value'=>$historical,'weight'=>$completion!==null&&$completion<$minRate?35:25);
        if(is_array($pace)&&isset($pace['first'][$column])&&isset($pace['last'][$column])){$delta=max(0,(float)$pace['last'][$column]-(float)$pace['first'][$column]);$remaining=max(0,100-(float)$progress['rate']);$paceValue=$current+$delta*($remaining/max(1,(float)$progress['rate']))*0.8;if($delta>0)$candidates[]=array('type'=>'RECENT_PACE','value'=>$paceValue,'weight'=>20);}
        $forecast=self::weightedMedian($candidates);if($forecast===null)$forecast=$current;$forecast=max($current,$forecast);$method=count($candidates)===0?'COLD_START':(count($candidates)>1?'COMPLETION_AND_HISTORICAL':$candidates[0]['type']);
        $fallback=isset($pattern['fallback_level'])?(string)$pattern['fallback_level']:'COLD_START';$sample=isset($pattern['sample_month_count'])?(int)$pattern['sample_month_count']:0;$vol=isset($pattern['completion_volatility'])&&$pattern['completion_volatility']!==null?(float)$pattern['completion_volatility']:35;$width=0.12+min(0.35,$vol/100)+($sample<3?0.15:0)+($fallback==='COLD_START'?0.18:0);$width=min(0.55,$width);$low=max($current,$forecast*(1-$width));$high=max($low,$forecast*(1+$width));
        $analyzable=$completion===null?0:100;$confidence=self::confidence($pattern,$progress['rate'],$analyzable);if($completion!==null&&$completion<$minRate&&$confidence!==null)$confidence=max(0,$confidence-15);$over=AiCostProjectionRiskService::overinputGrade($current,$forecast,$historical,$completion);$missing=AiCostProjectionRiskService::missingPossibilityGrade($completion,$progress['rate'],isset($pattern['event_count'])?$pattern['event_count']:0,isset($pattern['average_input_lag_days'])?$pattern['average_input_lag_days']:null);
        $row=array('cost_type'=>$cost,'current_input_amount'=>round($current,2),'expected_completion_rate'=>$completion,'expected_unentered_amount'=>round(max(0,$forecast-$current),2),'final_forecast_amount'=>round($forecast,2),'forecast_low_amount'=>round($low,2),'forecast_high_amount'=>round($high,2),'forecast_confidence_score'=>$confidence,'forecast_confidence_grade'=>self::confidenceGrade($confidence),'forecast_method'=>$method,'fallback_level'=>$fallback,'sample_count'=>$sample,'event_count'=>isset($pattern['event_count'])?(int)$pattern['event_count']:0,'average_input_lag_days'=>isset($pattern['average_input_lag_days'])?$pattern['average_input_lag_days']:null,'completion_volatility'=>isset($pattern['completion_volatility'])?$pattern['completion_volatility']:null,'late_bulk_rate'=>isset($pattern['late_bulk_rate'])?$pattern['late_bulk_rate']:null,'correction_rate'=>isset($pattern['correction_rate'])?$pattern['correction_rate']:null,'month_move_rate'=>isset($pattern['month_move_rate'])?$pattern['month_move_rate']:null,'overinput_grade'=>$over,'missing_possibility_grade'=>$missing,'data_status'=>$completion===null?'INSUFFICIENT':($sample>=3?'READY':'LIMITED'),'calculation_version'=>self::CALCULATION_VERSION,'candidate_data'=>$candidates,'progress_rate'=>$progress['rate']);$row['anomaly_types']=AiCostProjectionRiskService::anomalyTypes($row);return $row;
    }

    public static function calculateProject($pdo,$snapshot,$oldCategories,$pace)
    {
        $categories=array();$patterns=array();$totals=array('current'=>0.0,'forecast'=>0.0,'low'=>0.0,'high'=>0.0,'completion_weighted'=>0.0,'completion_base'=>0.0,'confidence_weighted'=>0.0,'confidence_base'=>0.0);$sample=0;$available=0;$methods=array();$fallbacks=array();
        foreach(self::categories() as $cost=>$column){$pattern=AiInputCompletionPatternService::loadBestPattern($pdo,$snapshot['snapshot_date'],$snapshot['target_ym'],(int)$snapshot['project_id'],$cost);$patterns[$cost]=$pattern;$old=isset($oldCategories[$cost])&&is_array($oldCategories[$cost])?$oldCategories[$cost]:array();$row=self::calculateCategory($pdo,$snapshot,$cost,$column,$pattern,$old,$pace);$categories[]=$row;$amount=max(1,(float)$row['current_input_amount']);$totals['current']+=$row['current_input_amount'];$totals['forecast']+=$row['final_forecast_amount'];$totals['low']+=$row['forecast_low_amount'];$totals['high']+=$row['forecast_high_amount'];if($row['expected_completion_rate']!==null){$totals['completion_weighted']+=(float)$row['expected_completion_rate']*$amount;$totals['completion_base']+=$amount;$available++;}if($row['forecast_confidence_score']!==null){$totals['confidence_weighted']+=(float)$row['forecast_confidence_score']*$amount;$totals['confidence_base']+=$amount;}$sample=max($sample,(int)$row['sample_count']);$methods[$row['forecast_method']]=isset($methods[$row['forecast_method']])?$methods[$row['forecast_method']]+1:1;$fallbacks[$row['fallback_level']]=isset($fallbacks[$row['fallback_level']])?$fallbacks[$row['fallback_level']]+1:1;}
        arsort($methods);arsort($fallbacks);$method=count($methods)?key($methods):'INSUFFICIENT';$fallback=count($fallbacks)?key($fallbacks):'COLD_START';$completion=$totals['completion_base']>0?round($totals['completion_weighted']/$totals['completion_base'],3):null;$confidence=$totals['confidence_base']>0?round($totals['confidence_weighted']/$totals['confidence_base'],2):null;$cumulative=(float)$snapshot['cumulative_input_amount'];$projectedCumulative=max($cumulative,$cumulative-$totals['current']+$totals['forecast']);$risk=AiCostProjectionRiskService::summarizeProject($categories,$projectedCumulative,(float)$snapshot['contract_amount'],$confidence);
        return array('project_id'=>(int)$snapshot['project_id'],'project_name_snapshot'=>(string)$snapshot['project_name_snapshot'],'project_status_snapshot'=>(string)$snapshot['project_status_snapshot'],'current_input_amount'=>round($totals['current'],2),'expected_completion_rate'=>$completion,'expected_unentered_amount'=>round(max(0,$totals['forecast']-$totals['current']),2),'final_forecast_amount'=>round(max($totals['current'],$totals['forecast']),2),'forecast_low_amount'=>round(max($totals['current'],$totals['low']),2),'forecast_high_amount'=>round(max($totals['low'],$totals['high']),2),'forecast_confidence_score'=>$confidence,'forecast_confidence_grade'=>self::confidenceGrade($confidence),'forecast_method'=>count($methods)>1?'MIXED':$method,'fallback_level'=>$fallback,'sample_count'=>$sample,'category_analyzable_rate'=>round($available/count(self::categories())*100,3),'cumulative_current_input_amount'=>round($cumulative,2),'cumulative_projected_input_amount'=>round($projectedCumulative,2),'contract_amount'=>(float)$snapshot['contract_amount'],'projected_cumulative_cost_rate'=>$risk['contract_risk']['rate'],'contract_risk_grade'=>$risk['contract_risk']['grade'],'overinput_grade'=>$risk['overinput_grade'],'missing_possibility_grade'=>$risk['missing_possibility_grade'],'anomaly_count'=>count($risk['anomaly_types']),'data_status'=>$confidence===null?'INSUFFICIENT':($available<count(self::categories())?'LIMITED':'READY'),'calculation_version'=>self::CALCULATION_VERSION,'method_data'=>array('methods'=>$methods,'fallbacks'=>$fallbacks),'warning_data'=>$confidence===null?array('예측 신뢰도를 계산할 자료가 부족합니다.'):array(),'risk_data'=>$risk,'categories'=>$categories,'patterns'=>$patterns);
    }

    private static function actor($trigger){if($trigger==='CLI'||$trigger==='SYSTEM')return array('id'=>null,'name'=>null);$user=Auth::user();$name=isset($user['name'])?(string)$user['name']:'';$name=function_exists('mb_substr')?mb_substr($name,0,100,'UTF-8'):substr($name,0,100);return array('id'=>isset($user['employee_id'])?(int)$user['employee_id']:null,'name'=>$name!==''?$name:null);}
    private static function acquireLock($pdo,$context){$name='cpms_ai_cost_forecast_v2_'.str_replace('-','',$context['analysis_date']).'_'.str_replace('-','',$context['target_ym']);try{$st=$pdo->prepare('SELECT GET_LOCK(:name,0)');if(!$st||!$st->execute(array(':name'=>$name)))return array('ok'=>true,'name'=>'');return array('ok'=>(int)$st->fetchColumn()===1,'name'=>$name);}catch(Exception $e){return array('ok'=>true,'name'=>'');}}
    private static function releaseLock($pdo,$lock){if(empty($lock['name']))return;try{$st=$pdo->prepare('SELECT RELEASE_LOCK(:name)');if($st)$st->execute(array(':name'=>$lock['name']));}catch(Exception $e){}}
    private static function createRun($pdo,$context,$trigger,$fingerprint,$count){$actor=self::actor($trigger);$uid=hash('sha256',uniqid('',true).microtime(true).mt_rand());$now=date('Y-m-d H:i:s');$sql='INSERT INTO `'.self::RUN_TABLE.'` (run_uid,analysis_date,target_ym,snapshot_date,trigger_type,run_status,calculation_version,source_fingerprint,project_count,actor_employee_id,actor_name,started_at,created_at) VALUES (:uid,:date,:ym,:snapshot,:trigger,\'RUNNING\',:version,:fingerprint,:count,:actor_id,:actor_name,:started,:created)';$st=$pdo->prepare($sql);if(!$st||!$st->execute(array(':uid'=>$uid,':date'=>$context['analysis_date'],':ym'=>$context['target_ym'],':snapshot'=>$context['snapshot_date'],':trigger'=>$trigger,':version'=>self::CALCULATION_VERSION,':fingerprint'=>$fingerprint,':count'=>$count,':actor_id'=>$actor['id'],':actor_name'=>$actor['name'],':started'=>$now,':created'=>$now)))return 0;return (int)$pdo->lastInsertId();}
    private static function finishRun($pdo,$runId,$status,$counts,$totals,$error){$sql='UPDATE `'.self::RUN_TABLE.'` SET run_status=:status,success_count=:success,failure_count=:failure,insufficient_count=:insufficient,current_input_total=:current,final_forecast_total=:forecast,forecast_low_total=:low,forecast_high_total=:high,finished_at=:finished,error_summary=:error WHERE id=:id';$st=$pdo->prepare($sql);if($st)$st->execute(array(':status'=>$status,':success'=>$counts['success'],':failure'=>$counts['failure'],':insufficient'=>$counts['insufficient'],':current'=>$totals['current'],':forecast'=>$totals['forecast'],':low'=>$totals['low'],':high'=>$totals['high'],':finished'=>date('Y-m-d H:i:s'),':error'=>$error,':id'=>$runId));}
