    private static function saveResult($pdo,$runId,$context,$fingerprint,$row){$now=date('Y-m-d H:i:s');$sql='INSERT INTO `'.self::RESULT_TABLE.'` (run_id,analysis_date,target_ym,snapshot_date,project_id,project_name_snapshot,project_status_snapshot,current_input_amount,expected_completion_rate,expected_unentered_amount,final_forecast_amount,forecast_low_amount,forecast_high_amount,forecast_confidence_score,forecast_confidence_grade,forecast_method,fallback_level,sample_count,category_analyzable_rate,cumulative_current_input_amount,cumulative_projected_input_amount,contract_amount,projected_cumulative_cost_rate,contract_risk_grade,overinput_grade,missing_possibility_grade,anomaly_count,data_status,calculation_version,source_fingerprint,method_data,warning_data,risk_data,first_created_at,last_calculated_at,calculation_count,created_at,updated_at) VALUES (:run,:date,:ym,:snapshot,:project,:name,:project_status,:current,:completion,:unentered,:forecast,:low,:high,:confidence,:grade,:method,:fallback,:samples,:analyzable,:cumulative,:projected,:contract,:cost_rate,:contract_risk,:overinput,:missing,:anomalies,:data_status,:version,:fingerprint,:methods,:warnings,:risk,:first,:last,1,:created,:updated) ON DUPLICATE KEY UPDATE run_id=VALUES(run_id),project_name_snapshot=VALUES(project_name_snapshot),project_status_snapshot=VALUES(project_status_snapshot),current_input_amount=VALUES(current_input_amount),expected_completion_rate=VALUES(expected_completion_rate),expected_unentered_amount=VALUES(expected_unentered_amount),final_forecast_amount=VALUES(final_forecast_amount),forecast_low_amount=VALUES(forecast_low_amount),forecast_high_amount=VALUES(forecast_high_amount),forecast_confidence_score=VALUES(forecast_confidence_score),forecast_confidence_grade=VALUES(forecast_confidence_grade),forecast_method=VALUES(forecast_method),fallback_level=VALUES(fallback_level),sample_count=VALUES(sample_count),category_analyzable_rate=VALUES(category_analyzable_rate),cumulative_current_input_amount=VALUES(cumulative_current_input_amount),cumulative_projected_input_amount=VALUES(cumulative_projected_input_amount),contract_amount=VALUES(contract_amount),projected_cumulative_cost_rate=VALUES(projected_cumulative_cost_rate),contract_risk_grade=VALUES(contract_risk_grade),overinput_grade=VALUES(overinput_grade),missing_possibility_grade=VALUES(missing_possibility_grade),anomaly_count=VALUES(anomaly_count),data_status=VALUES(data_status),calculation_version=VALUES(calculation_version),source_fingerprint=VALUES(source_fingerprint),method_data=VALUES(method_data),warning_data=VALUES(warning_data),risk_data=VALUES(risk_data),last_calculated_at=VALUES(last_calculated_at),calculation_count=calculation_count+1,updated_at=VALUES(updated_at)';$st=$pdo->prepare($sql);if(!$st)return false;return $st->execute(array(':run'=>$runId,':date'=>$context['analysis_date'],':ym'=>$context['target_ym'],':snapshot'=>$context['snapshot_date'],':project'=>$row['project_id'],':name'=>$row['project_name_snapshot'],':project_status'=>$row['project_status_snapshot'],':current'=>$row['current_input_amount'],':completion'=>$row['expected_completion_rate'],':unentered'=>$row['expected_unentered_amount'],':forecast'=>$row['final_forecast_amount'],':low'=>$row['forecast_low_amount'],':high'=>$row['forecast_high_amount'],':confidence'=>$row['forecast_confidence_score'],':grade'=>$row['forecast_confidence_grade'],':method'=>$row['forecast_method'],':fallback'=>$row['fallback_level'],':samples'=>$row['sample_count'],':analyzable'=>$row['category_analyzable_rate'],':cumulative'=>$row['cumulative_current_input_amount'],':projected'=>$row['cumulative_projected_input_amount'],':contract'=>$row['contract_amount'],':cost_rate'=>$row['projected_cumulative_cost_rate'],':contract_risk'=>$row['contract_risk_grade'],':overinput'=>$row['overinput_grade'],':missing'=>$row['missing_possibility_grade'],':anomalies'=>$row['anomaly_count'],':data_status'=>$row['data_status'],':version'=>self::CALCULATION_VE