    public static function forecastLatest($pdo=null,$triggerType='SYSTEM')
    {
        $pdo=self::pdo($pdo);$empty=array('ok'=>false,'status'=>'FAILED','projects'=>0,'success'=>0,'failed'=>0,'message'=>'V2 최종 투입비 예측을 실행하지 못했습니다.');if(!$pdo){$empty['message']='DB 연결 상태를 확인할 수 없습니다.';return $empty;}if(!self::isInstalled($pdo)){$empty['message']='V2 예측 테이블을 먼저 설치해주세요.';return $empty;}$context=self::latestSnapshotContext($pdo);if(empty($context['available'])){$empty['message']='먼저 일일 스냅샷을 생성해주세요.';return $empty;}$snapshots=self::loadSnapshots($pdo,$context);if(count($snapshots)===0){$empty['message']='예측할 현장 스냅샷이 없습니다.';return $empty;}$old=self::oldForecastMap($pdo,$context);$pace=self::recentPaceMap($pdo,$context);$fingerprint=self::sourceFingerprint($context,$snapshots,array('pattern_date'=>$context['analysis_date']));$lock=self::acquireLock($pdo,$context);if(empty($lock['ok'])){$empty['message']='이미 V2 예측 계산이 진행 중입니다.';return $empty;}$trigger=in_array(strtoupper((string)$triggerType),array('MANUAL','CLI','SYSTEM'),true)?strtoupper((string)$triggerType):'SYSTEM';$runId=0;
        try{$runId=self::createRun($pdo,$context,$trigger,$fingerprint,count($snapshots));if($runId<=0)throw new Exception('run');$counts=array('success'=>0,'failure'=>0,'insufficient'=>0);$totals=array('current'=>0.0,'forecast'=>0.0,'low'=>0.0,'high'=>0.0);foreach($snapshots as $snapshot){try{$projectId=(int)$snapshot['project_id'];$row=self::calculateProject($pdo,$snapshot,isset($old[$projectId])?$old[$projectId]:array(),isset($pace[$projectId])?$pace[$projectId]:array());$categoryOk=true;foreach($row['categories'] as $category)if(!self::saveCategory($pdo,$runId,$context,$projectId,$category))$categoryOk=false;if(!$categoryOk||!self::saveResult($pdo,$runId,$context,$fingerprint,$row))throw new Exception('save');$counts['success']++;if($row['forecast_confidence_grade']==='INSUFFICIENT')$counts['insufficient']++;$totals['current']+=$row['current_input_amount'];$totals['forecast']+=$row['final_forecast_amount'];$totals['low']+=$row['forecast_low_amount'];$totals['high']+=$row['forecast_high_amount'];}catch(Exception $e){$counts['failure']++;error_log('[AI Forecast V2] project calculation failed');}}$status=$counts['success']===0?'FAILED':($counts['failure']>0?'PARTIAL':'COMPLETED');self::finishRun($pdo,$runId,$status,$counts,$totals,$counts['failure']>0?'일부 현장 V2 예측 실패: '.$counts['failure'].'건':null);self::releaseLock($pdo,$lock);return array('ok'=>$counts['success']>0,'status'=>$status,'projects'=>count($snapshots),'success'=>$counts['success'],'failed'=>$counts['failure'],'insufficient'=>$counts['insufficient'],'message'=>$status==='COMPLETED'?'V2 최종 투입비 예측을 완료했습니다.':($status==='PARTIAL'?'일부 현장을 제외하고 V2 예측을 완료했습니다.':'V2 예측에 실패했습니다.'));}catch(Exception $e){if($runId>0)self::finishRun($pdo,$runId,'FAILED',array('success'=>0,'failure'=>count($snapshots),'insufficient'=>0),array('current'=>0,'forecast'=>0,'low'=>0,'high'=>0),'V2 예측 실행 중 오류가 발생했습니다.');self::releaseLock($pdo,$lock);error_log('[AI Forecast V2] run failed');return $empty;}
    }

    public static function latestContext($pdo=null,$targetYm=''){$pdo=self::pdo($pdo);$empty=array('available'=>false,'calculation_version'=>self::CALCULATION_VERSION);if(!$pdo||!self::isInstalled($pdo))return $empty;try{$where='';$params=array(':result_version'=>self::CALCULATION_VERSION,':run_version'=>self::CALCULATION_VERSION);if(CostChangeService::validYm($targetYm)!==''){$where=' AND r.target_ym=:ym';$params[':ym']=$targetYm;}$sql='SELECT r.analysis_date,r.target_ym,r.snapshot_date,r.run_id,r.calculation_version FROM `'.self::RESULT_TABLE.'` r INNER JOIN `'.self::RUN_TABLE.'` u ON u.id=r.run_id AND u.run_status=\'COMPLETED\' AND u.calculation_version=:run_version WHERE r.calculation_version=:result_version'.$where.' ORDER BY r.analysis_date DESC,r.id DESC LIMIT 1';$st=$pdo->prepare($sql);if(!$st||!$st->execute($params))return $empty;$row=$st->fetch(PDO::FETCH_ASSOC);if(!is_array($row)||(string)$row['calculation_version']!==self::CALCULATION_VERSION)return $empty;$row['available']=true;return $row;}catch(Exception $e){return $empty;}}
    public static function latestCompanySummary($pdo=null,$targetYm=''){$pdo=self::pdo($pdo);$context=self::latestContext($pdo,$targetYm);$empty=array('available'=>false,'calculation_version'=>self::CALCULATION_VERSION,'project_count'=>0,'current_input_total'=>null,'expected_unentered_total'=>null,'final_forecast_total'=>null,'forecast_low_total'=>null,'forecast_high_total'=>null,'expected_completion_rate'=>null,'confidence_score'=>null,'confidence_grade'=>'INSUFFICIENT','overinput_count'=>0,'missing_count'=>0,'anomaly_count'=>0);if(empty($context['available']))return $empty;try{$sql='SELECT COUNT(*) AS project_count,SUM(current_input_amount) AS current_total,SUM(expected_unentered_amount) AS unentered_total,SUM(final_forecast_amount) AS forecast_total,SUM(forecast_low_amount) AS low_total,SUM(forecast_high_amount) AS high_total,SUM(CASE WHEN overinput_grade IN (\'WARNING\',\'CRITICAL\') THEN 1 ELSE 0 END) AS overinput_count,SUM(CASE WHEN missing_possibility_grade=\'HIGH\' THEN 1 ELSE 0 END) AS missing_count,SUM(anomaly_count) AS anomaly_count,SUM(CASE WHEN expected_completion_rate IS NOT NULL THEN expected_completion_rate*GREATEST(current_input_amount,1) ELSE 0 END)/NULLIF(SUM(CASE WHEN expected_completion_rate IS NOT NULL THEN GREATEST(current_input_amount,1) ELSE 0 END),0) AS completion_rate,SUM(CASE WHEN forecast_confidence_score IS NOT NULL THEN forecast_confidence_score*GREATEST(final_forecast_amount,1) ELSE 0 END)/NULLIF(SUM(CASE WHEN forecast_confidence_score IS NOT NULL THEN GREATEST(final_forecast_amount,1) ELSE 0 END),0) AS confidence_score,MAX(last_calculated_at) AS last_calculated_at FROM `'.self::RESULT_TABLE.'` WHERE analysis_date=:date AND target_ym=:ym AND run_id=:run_id AND calculation_version=:version';$st=$pdo->prepare($sql);if(!$st||!$st->execute(array(':date'=>$context['analysis_date'],':ym'=>$context['target_ym'],':run_id'=>(int)$context['run_id'],':version'=>self::CALCULATION_VERSION)))return $empty;$row=$st->fetch(PDO::FETCH_ASSOC);if(!is_array($row)||(int)$row['project_count']<=0)return $empty;$score=$row['confidence_score']===null?null:(float)$row['confidence_score'];return array('available'=>true,'calculation_version'=>self::CALCULATION_VERSION,'run_id'=>(int)$context['run_id'],'analysis_date'=>$context['analysis_date'],'target_ym'=>$context['target_ym'],'snapshot_date'=>$context['snapshot_date'],'project_count'=>(int)$row['project_count'],'current_input_total'=>$row['current_total']===null?null:(float)$row['current_total'],'expected_unentered_total'=>$row['unentered_total']===null?null:(float)$row['unentered_total'],'final_forecast_total'=>$row['forecast_total']===null?null:(float)$row['forecast_total'],'forecast_low_total'=>$row['low_total']===null?null:(float)$row['low_total'],'forecast_high_total'=>$row['high_total']===null?null:(float)$row['high_total'],'expected_completion_rate'=>$row['completion_rate']===null?null:(float)$row['completion_rate'],'confidence_score'=>$score,'confidence_grade'=>self::confidenceGrade($score),'overinput_count'=>(int)$row['overinput_count'],'missing_count'=>(int)$row['missing_count'],'anomaly_count'=>(int)$row['anomaly_count'],'last_calculated_at'=>(string)$row['last_calculated_at']);}catch(Exception $e){return $empty;}}
    public static function countResults($pdo,$context,$filters=array()){$pdo=self::pdo($pdo);if(!$pdo||empty($context['available']))return 0;try{$sql='SELECT COUNT(*) FROM `'.self::RESULT_TABLE.'` WHERE analysis_date=:date AND target_ym=:ym AND run_id=:run_id AND calculation_version=:version';$params=array(':date'=>$context['analysis_date'],':ym'=>$context['target_ym'],':run_id'=>(int)$context['run_id'],':version'=>self::CALCULATION_VERSION);if(isset($filters['project_id'])&&(int)$filters['project_id']>0){$sql.=' AND project_id=:project';$params[':project']=(int)$filters['project_id'];}$st=$pdo->prepare($sql);return $st&&$st->execute($params)?(int)$st->fetchColumn():0;}catch(Exception $e){return 0;}}
    public static function listResults($pdo,$context,$filters,$page,$perPage){$pdo=self::pdo($pdo);$page=max(1,(int)$page);$perPage=max(1,min(100,(int)$perPage));if(!$pdo||empty($context['available']))return array();try{$sql='SELECT * FROM `'.self::RESULT_TABLE.'` WHERE analysis_date=:date AND target_ym=:ym AND run_id=:run_id AND calculation_version=:version';$params=array(':date'=>$context['analysis_date'],':ym'=>$context['target_ym'],':run_id'=>(int)$context['run_id'],':version'=>self::CALCULATION_VERSION);if(isset($filters['project_id'])&&(int)$filters['project_id']>0){$sql.=' AND project_id=:project';$params[':project']=(int)$filters['project_id'];}$sql.=' ORDER BY CASE overinput_grade WHEN \'CRITICAL\' THEN 1 WHEN \'WARNING\' THEN 2 WHEN \'WATCH\' THEN 3 ELSE 4 END, final_forecast_amount DESC LIMIT :limit OFFSET :offset';$st=$pdo->prepare($sql);if(!$st)return array();foreach($params as $key=>$value)$st->bindValue($key,$value,is_int($value)?PDO::PARAM_INT:PDO::PARAM_STR);$st->bindValue(':limit',$perPage,PDO::PARAM_INT);$st->bindValue(':offset',($page-1)*$perPage,PDO::PARAM_INT);if(!$st->execute())return array();$rows=$st->fetchAll(PDO::FETCH_ASSOC);return is_array($rows)?$rows:array();}catch(Exception $e){return array();}}
    public static function categoryRows($pdo,$analysisDate,$targetYm,$projectId=0,$runId=0){$pdo=self::pdo($pdo);if(!$pdo||!self::isInstalled($pdo))return array();try{$sql='SELECT * FROM `'.self::CATEGORY_TABLE.'` WHERE analysis_date=:date AND target_ym=:ym AND calculation_version=:version';$params=array(':date'=>$analysisDate,':ym'=>$targetYm,':version'=>self::CALCULATION_VERSION);if((int)$runId>0){$sql.=' AND run_id=:run_id';$params[':run_id']=(int)$runId;}if((int)$projectId>0){$sql.=' AND project_id=:project';$params[':project']=(int)$projectId;}$sql.=' ORDER BY project_id,cost_type';$st=$pdo->prepare($sql);if(!$st||!$st->execute($params))return array();$rows=$st->fetchAll(PDO::FETCH_ASSOC);return is_array($rows)?$rows:array();}catch(Exception $e){return array();}}
    public static function availableMonths($pdo=null){$pdo=self::pdo($pdo);$rows=array();if(!$pdo||!self::isInstalled($pdo))return $rows;try{$sql='SELECT DISTINCT r.target_ym FROM `'.self::RESULT_TABLE.'` r INNER JOIN `'.self::RUN_TABLE.'` u ON u.id=r.run_id AND u.run_status=\'COMPLETED\' AND u.calculation_version=:run_version WHERE r.calculation_version=:result_version ORDER BY r.target_ym DESC LIMIT 36';$st=$pdo->prepare($sql);if(!$st||!$st->execute(array(':run_version'=>self::CALCULATION_VERSION,':result_version'=>self::CALCULATION_VERSION)))return $rows;foreach($st->fetchAll(PDO::FETCH_ASSOC) as $row)$rows[]=(string)$row['target_ym'];}catch(Exception $e){}return $rows;}
}
